package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type TempRec struct {
	TcSensor string
	TcF      decimal.Decimal
}

var WsEofFlag string = "N"
var WsC decimal.Decimal = decimal.NewFromInt(0)
var WsFreeze int64 = 0
var WsCount int64 = 0
var WsFEd string
var WsCEd string

var tempFile *os.File
var tempReader *bufio.Scanner
var tempRec TempRec

func isInputDone() bool {
	return WsEofFlag == "Y"
}

func fitPIC99(v int64) int64 {
	// keep low-order 2 digits
	m := v % 100
	if m < 0 {
		m += 100
		// For positive overflow we keep low-order digits, for negative
		// COBOL typically keeps magnitude. But counts never negative.
	}
	return m
}

func fitSigned(v decimal.Decimal, intDigits int, scale int) decimal.Decimal {
	// keep low-order digits that fit: total digits = intDigits+scale
	// Stored as integer = v * 10^scale
	shifted := v.Shift(int32(scale))
	// shifted should be integer (rounded already)
	// modulo 10^(intDigits+scale) preserving sign
	total := intDigits + scale
	mod := decimal.New(1, int32(total)) // 10^total
	// Use integer arithmetic on shifted
	// Truncate toward zero to get integer part
	// shifted is already scaled integer, but may have fractional due to decimal representation
	shifted = shifted.Truncate(0)
	signNeg := shifted.Sign() < 0
	abs := shifted.Abs()
	// abs mod mod
	// decimal Mod not directly, use DivMod via big int?
	// Convert to int64 when possible: intDigits up to 3+2=5 => fits in int64
	// Use IntPart
	// For safety use decimal's Mod via remainder: abs - floor(abs/mod)*mod
	q := abs.Div(mod).Truncate(0) // floor for positive
	rem := abs.Sub(q.Mul(mod))
	if signNeg {
		rem = rem.Neg()
	}
	// convert back
	return rem.Shift(int32(-scale))
}

func formatZZ9_9(v decimal.Decimal) string {
	// PIC ZZ9.9 len 5 : 3 int digits, 1 dec
	intDigits := 3
	scale := 1
	// overflow truncation already done? For TC-F, PIC 9(3)V9 fits, but WS-F-ED truncates high order if needed
	// Apply low-order truncation for display
	// Extract integer part low-order
	// Keep low-order digits
	// Build absolute value handling sign (TC-F never negative)
	neg := v.Sign() < 0
	if neg {
		v = v.Neg()
	}
	// Truncate/drop high order integer digits: modulo 10^intDigits for integer part
	// Keep decimals as is (scale 1)
	// We can do fit to picture width: total integer+scale digits
	// For Z field, overflow drops high order integer digits
	powInt := int64(1)
	for i := 0; i < intDigits; i++ {
		powInt *= 10
	}
	// separate integer and fractional
	// Get scaled integer
	scaled := v.Shift(int32(scale)).Truncate(0) // e.g., 32.0 => 320
	absScaled := scaled.Abs()
	// For overflow, keep low-order intDigits + scale digits -> modulo 10^(intDigits+scale)
	modVal := decimal.New(1, int32(intDigits+scale))
	q := absScaled.Div(modVal).Truncate(0)
	rem := absScaled.Sub(q.Mul(modVal))
	// rem is 0..10^(int+scale)-1
	remInt := rem.IntPart() // fits
	intPart := remInt / int64(pow10(scale))
	fracPart := remInt % int64(pow10(scale))

	intStr := fmt.Sprintf("%0*d", intDigits, intPart)
	// Z suppression
	outInt := make([]byte, intDigits)
	blanking := true
	for i := 0; i < intDigits; i++ {
		isLast := i == intDigits-1
		ch := intStr[i]
		if blanking {
			if ch == '0' && !isLast {
				outInt[i] = ' '
			} else {
				outInt[i] = ch
				blanking = false
			}
		} else {
			outInt[i] = ch
		}
	}
	fracStr := fmt.Sprintf("%0*d", scale, fracPart)
	result := string(outInt) + "." + fracStr
	if neg {
		// not used for WS-F-ED but handle
		result = "-" + result
	}
	return result
}

func pow10(n int) int64 {
	p := int64(1)
	for i := 0; i < n; i++ {
		p *= 10
	}
	return p
}

func formatMinusZZ9_99(v decimal.Decimal) string {
	// PIC -ZZ9.99 len 7 : sign + 3 int + . +2 dec
	intDigits := 3
	scale := 2
	neg := v.Sign() < 0
	abs := v.Abs()
	// overflow low-order truncation
	modVal := decimal.New(1, int32(intDigits+scale))
	scaled := abs.Shift(int32(scale)).Truncate(0)
	q := scaled.Div(modVal).Truncate(0)
	rem := scaled.Sub(q.Mul(modVal))
	remInt := rem.IntPart()
	intPart := remInt / int64(pow10(scale))
	fracPart := remInt % int64(pow10(scale))

	intStr := fmt.Sprintf("%0*d", intDigits, intPart)
	outInt := make([]byte, intDigits)
	blanking := true
	for i := 0; i < intDigits; i++ {
		isLast := i == intDigits-1
		ch := intStr[i]
		if blanking {
			if ch == '0' && !isLast {
				outInt[i] = ' '
			} else {
				outInt[i] = ch
				blanking = false
			}
		} else {
			outInt[i] = ch
		}
	}
	fracStr := fmt.Sprintf("%0*d", scale, fracPart)
	signChar := ' '
	if neg {
		signChar = '-'
	}
	return string(signChar) + string(outInt) + "." + fracStr
}

func formatPIC99(v int64) string {
	// zero-padded to 2 digits, with overflow already applied and low-order kept
	if v < 0 {
		v = -v
	}
	return fmt.Sprintf("%02d", v%100)
}

func parseTempRec(line string) TempRec {
	if len(line) < 8 {
		line = line + strings.Repeat(" ", 8-len(line))
	}
	if len(line) > 8 {
		line = line[:8]
	}
	sensor := line[0:4]
	sF := line[4:8]
	// PIC 9(3)V9 digits only
	var n int64
	for _, c := range sF {
		if c >= '0' && c <= '9' {
			n = n*10 + int64(c-'0')
		} else {
			// treat non-digit as 0? COBOL would expect digits; treat as 0
			n = n * 10
		}
	}
	d := decimal.New(n, -1)
	return TempRec{TcSensor: sensor, TcF: d}
}

func MAIN_PARA() {
	var err error
	tempFile, err = os.Open("input.dat")
	if err != nil {
		fmt.Fprintf(os.Stderr, "open input.dat: %v\n", err)
		os.Exit(1)
	}
	defer tempFile.Close()
	tempReader = bufio.NewScanner(tempFile)
	// allow long lines
	READ_PARA()
	for !isInputDone() {
		PROCESS_PARA()
	}
	tempFile.Close()
	// DISPLAY "READINGS: " WS-COUNT " BELOW ZERO: " WS-FREEZE
	fmt.Printf("READINGS: %s BELOW ZERO: %s\n", formatPIC99(WsCount), formatPIC99(WsFreeze))
}

func READ_PARA() {
	if tempReader.Scan() {
		line := tempReader.Text()
		// Scanner strips newline, but keeps other spaces? It trims \r. Need to preserve spaces.
		// Scanner returns line without newline, which matches record padded spaces already trimmed trailing?
		// COBOL LINE SEQUENTIAL pads on right, so trailing spaces are significant but Scanner trims?
		// Actually trailing spaces would be removed by scanner? But Go Scanner returns line without trailing \r\n but keeps other spaces.
		// However reading via Scanner will keep spaces except newline. But if line had trailing spaces, they may be preserved.
		// Need to handle that scanner strips final \n only.
		tempRec = parseTempRec(line)
	} else {
		WsEofFlag = "Y"
	}
}

func PROCESS_PARA() {
	// COMPUTE WS-C ROUNDED = (TC-F - 32) * 5 / 9
	diff := tempRec.TcF.Sub(decimal.NewFromInt(32))
	mul := diff.Mul(decimal.NewFromInt(5))
	div := mul.Div(decimal.NewFromInt(9))
	rounded := div.Round(2)
	WsC = fitSigned(rounded, 3, 2)

	if WsC.Sign() < 0 {
		WsFreeze = fitPIC99(WsFreeze + 1)
	}
	WsCount = fitPIC99(WsCount + 1)

	WsFEd = formatZZ9_9(tempRec.TcF)
	WsCEd = formatMinusZZ9_99(WsC)
	fmt.Printf("%s %sF %sC\n", tempRec.TcSensor, WsFEd, WsCEd)
	READ_PARA()
}

func main() {
	MAIN_PARA()
}
